export default function Logos() {
  const [inView, setInView] = useState(false);
  const sectionRef = useRef(null);

  useEffect(() => {
    const el = sectionRef.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      ([e]) => { if (e.isIntersecting) setInView(true); },
      { threshold: 0.1 }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, []);

  /* We duplicate the array to create a seamless marquee loop */
  const row1 = LOGOS.slice(0, 6);
  const row2 = LOGOS.slice(6, 11);

  return (
    <section ref={sectionRef} className="lg-section">
      {/* Top shimmer line */}
      <div aria-hidden className="lg-shimmer-line" />
      <div aria-hidden className="lg-shimmer-glow" />

      <p
        className="lg-label"
        style={{
          opacity: inView ? 1 : 0,
          transform: inView ? "none" : "translateY(12px)",
          transition: "opacity 0.7s ease, transform 0.7s ease",
        }}
      >
        Companies of all sizes trust Resend to deliver their most important emails.
      </p>

      {/* ── Row 1 marquee (6 logos) ── */}
      <div
        className="lg-marquee-wrapper"
        style={{
          opacity: inView ? 1 : 0,
          transform: inView ? "none" : "translateY(16px)",
          transition: "opacity 0.75s ease 0.15s, transform 0.75s ease 0.15s",
        }}
      >
        <div className="lg-marquee lg-marquee--left">
          {[...row1, ...row1].map((logo, i) => (
            <div key={`r1-${i}`} className="lg-logo-wrap" title={logo.name}>
              {logo.svg}
            </div>
          ))}
        </div>
      </div>

      {/* ── Row 2 marquee (5 logos, scroll opposite direction) ── */}
      <div
        className="lg-marquee-wrapper"
        style={{
          opacity: inView ? 1 : 0,
          transform: inView ? "none" : "translateY(16px)",
          transition: "opacity 0.75s ease 0.28s, transform 0.75s ease 0.28s",
        }}
      >
        <div className="lg-marquee lg-marquee--right">
          {[...row2, ...row2, ...row2].map((logo, i) => (
            <div key={`r2-${i}`} className="lg-logo-wrap" title={logo.name}>
              {logo.svg}
            </div>
          ))}
        </div>
      </div>

      <style>{`
        /* ------- section shell ------- */
        .lg-section {
          position: relative;
          max-width: 82rem;
          margin: 0 auto;
          padding: 5rem 0 6rem;
          border-top: 1px solid rgba(255,255,255,0.07);
          display: flex;
          flex-direction: column;
          align-items: center;
          overflow: hidden;
        }

        /* Top shimmer */
        .lg-shimmer-line {
          position: absolute;
          left: 50%; top: 0;
          transform: translateX(-50%);
          width: 320px; height: 1px;
          background: linear-gradient(90deg, transparent, rgba(180,180,180,0.6) 50%, transparent);
          pointer-events: none;
        }
        .lg-shimmer-glow {
          position: absolute;
          left: 50%; top: 0;
          transform: translateX(-50%) translateY(-50%);
          width: 500px; height: 320px;
          background: radial-gradient(rgba(200,200,200,0.06) 0%, transparent 70%);
          pointer-events: none;
        }

        /* Label */
        .lg-label {
          font-size: 0.9375rem;
          font-weight: 400;
          color: rgba(255,255,255,0.38);
          text-align: center;
          max-width: 42ch;
          line-height: 1.65;
          margin-bottom: 3rem;
          padding: 0 1.5rem;
          position: relative;
          z-index: 1;
        }

        /* ------- Marquee container ------- */
        .lg-marquee-wrapper {
          width: 100%;
          overflow: hidden;
          /* edge fade */
          -webkit-mask-image: linear-gradient(
            to right,
            transparent 0%,
            black 10%,
            black 90%,
            transparent 100%
          );
          mask-image: linear-gradient(
            to right,
            transparent 0%,
            black 10%,
            black 90%,
            transparent 100%
          );
          margin-bottom: 0;
        }
        .lg-marquee-wrapper + .lg-marquee-wrapper { margin-top: 0; }

        /* ------- Marquee track ------- */
        .lg-marquee {
          display: flex;
          align-items: center;
          width: max-content;
          animation-timing-function: linear;
          animation-iteration-count: infinite;
        }
        .lg-marquee--left {
          animation: lg-scroll-left 30s linear infinite;
        }
        .lg-marquee--right {
          animation: lg-scroll-right 38s linear infinite;
        }

        @keyframes lg-scroll-left {
          0%   { transform: translateX(0); }
          100% { transform: translateX(-50%); }
        }
        @keyframes lg-scroll-right {
          0%   { transform: translateX(-33.333%); }
          100% { transform: translateX(0); }
        }

        /* Pause on hover */
        .lg-marquee-wrapper:hover .lg-marquee {
          animation-play-state: paused;
        }

        /* ------- Logo cell ------- */
        .lg-logo-wrap {
          display: flex;
          align-items: center;
          justify-content: center;
          padding: 1.75rem 2.5rem;
          opacity: 0.4;
          transition: opacity 0.3s ease, transform 0.3s ease, filter 0.3s ease;
          cursor: default;
          flex-shrink: 0;
        }
        .lg-logo-wrap:hover {
          opacity: 1;
          filter: drop-shadow(0 0 8px rgba(255,255,255,0.25));
        }

        /* ------- SVG sizing ------- */
        .logo-svg {
          height: 22px;
          width: auto;
          max-width: 110px;
          display: block;
          color: white; /* for currentColor logos */
        }

        /* Responsive tweaks */
        @media (max-width: 640px) {
          .lg-section { padding: 3.5rem 0 4.5rem; }
          .logo-svg { height: 18px; max-width: 85px; }
          .lg-logo-wrap { padding: 1.25rem 1.5rem; }
          .lg-marquee--left  { animation-duration: 22s; }
          .lg-marquee--right { animation-duration: 28s; }
        }
      `}</style>
    </section>
  );
}
